import assert from "node:assert/strict";
const { memoizeAsync } = await import(process.cwd() + "/src/index.ts");
const nonce = Math.random().toString(36).slice(2);
let calls = 0;
let release;
const pending = new Promise((resolve) => {
  release = resolve;
});
const getShared = memoizeAsync(() => {
  calls += 1;
  return pending;
});
const first = getShared();
const second = getShared();
await Promise.resolve();
assert.equal(calls, 1);
release({ value: nonce });
assert.deepEqual(await Promise.all([first, second]), [{ value: nonce }, { value: nonce }]);
assert.deepEqual(await getShared(), { value: nonce });
assert.equal(calls, 1);
const failure = new Error("retry-" + nonce);
let attempts = 0;
const getRetryable = memoizeAsync(() => {
  attempts += 1;
  return attempts === 1 ? Promise.reject(failure) : Promise.resolve("ok-" + nonce);
});
await assert.rejects(getRetryable(), (error) => error === failure);
assert.equal(await getRetryable(), "ok-" + nonce);
assert.equal(await getRetryable(), "ok-" + nonce);
assert.equal(attempts, 2);

import assert from "node:assert/strict";
const { pipeStream } = await import(process.cwd() + "/src/index.ts");
const nonce = Math.random().toString(36).slice(2);
let sourceController;
let cancelled;
let destinationAbort;
let markWritten;
const wrote = new Promise((resolve) => { markWritten = resolve; });
const source = new ReadableStream({
  start(controller) { sourceController = controller; controller.enqueue("chunk-" + nonce); },
  cancel(reason) { cancelled = reason; },
});
const destination = new WritableStream({
  write() { markWritten(); },
  abort(reason) { destinationAbort = reason; },
});
const aborter = new AbortController();
const reason = new Error("cancel-" + nonce);
const transfer = pipeStream(source, destination, aborter.signal);
await wrote;
aborter.abort(reason);
const settled = transfer.then(
  (value) => ({ ok: true, value }),
  (error) => ({ ok: false, error }),
);
const timedOut = Symbol("timed out");
let timer;
const outcome = await Promise.race([
  settled,
  new Promise((resolve) => { timer = setTimeout(() => resolve(timedOut), 400); }),
]);
clearTimeout(timer);
if (outcome === timedOut) {
  sourceController.close();
  await settled;
  assert.fail("pipeStream did not finish after the signal aborted");
}
assert.equal(outcome.ok, false);
assert.equal(outcome.error, reason);
assert.equal(cancelled, reason);
assert.equal(destinationAbort, reason);
assert.equal(source.locked, false);
assert.equal(destination.locked, false);
const normalSource = new ReadableStream({
  start(controller) { controller.enqueue("normal-" + nonce); controller.close(); },
});
const values = [];
const normalDestination = new WritableStream({
  write(value) { values.push(value); },
});
await pipeStream(normalSource, normalDestination);
assert.deepEqual(values, ["normal-" + nonce]);
assert.equal(normalSource.locked, false);
assert.equal(normalDestination.locked, false);

import assert from "node:assert/strict";
const { parseManifest, loadRegistryManifest } = await import(process.cwd()+"/src/index.ts");
const nonce=Math.random().toString(36).slice(2);
const valid={version:"v-"+nonce,entries:[{id:"id-"+nonce,path:"path/"+nonce,vendor:{revision:nonce}}],vendor:{retained:nonce}};
const invalid=[
  {value:null,field:null},{value:[],field:null},{value:7,field:null},
  {value:{entries:[]},field:"version"},{value:{version:7,entries:[]},field:"version"},
  {value:{version:"",entries:[]},field:"version"},
  {value:{version:"v"},field:"entries"},{value:{version:"v",entries:{}},field:"entries"},
  {value:{version:"v",entries:[null]},field:"entries[0]"},
  {value:{version:"v",entries:[7]},field:"entries[0]"},
  {value:{version:"v",entries:[{id:0,path:"p"}]},field:"entries[0].id"},
  {value:{version:"v",entries:[{id:"",path:"p"}]},field:"entries[0].id"},
  {value:{version:"v",entries:[{path:"p"}]},field:"entries[0].id"},
  {value:{version:"v",entries:[{id:"i",path:8}]},field:"entries[0].path"},
  {value:{version:"v",entries:[{id:"i",path:""}]},field:"entries[0].path"},
  {value:{version:"v",entries:[{id:"i"}]},field:"entries[0].path"},
];
for(const load of [parseManifest,loadRegistryManifest]){
  assert.deepEqual(load(JSON.stringify(valid)),valid);
  assert.deepEqual(load(JSON.stringify({version:"v",entries:[]})),{version:"v",entries:[]});
  assert.throws(()=>load("{"),e=>e instanceof Error && /JSON/i.test(e.message));
  for(const {value,field} of invalid){
    assert.throws(()=>load(JSON.stringify(value)),e=>{
      if(!(e instanceof Error))return false;
      if(field===null)return e.message.length>0;
      // Dot/bracket and JSON-pointer forms identify the same public field path.
      const normalized=e.message.replace(/\[(\d+)\]/g,".$1").replaceAll("/",".");
      return normalized.includes(field.replace(/\[(\d+)\]/g,".$1"));
    });
  }
}
